#!/bin/sh
# Files that name the same imported brand are generated by separate
# compiler runs, then included and linked into one program.
set -eu
CAPNP=$1
CAPNPC=$2
ROOT=$3
# Meson names a library target relative to the build directory.
LIB=$(cd "$(dirname "$4")" && pwd)/$(basename "$4")
# `meson.build` passes the configured host compilers.
CC=${CC:?}
CXX=${CXX:?}
# `EXE_WRAPPER`, or the `MESON_EXE_WRAPPER` meson sets on a cross
# build, runs a cross-built sample.
EXE_WRAPPER=${EXE_WRAPPER:-${MESON_EXE_WRAPPER:-}}
run_bin() {
	if [ -n "${EXE_WRAPPER:-}" ]; then
		# The wrapper can be several words, e.g. `env VAR=... qemu-s390x`.
		set -f
		# shellcheck disable=SC2086
		set -- $EXE_WRAPPER "$@"
		set +f
		"$@"
	else
		"$@"
	fi
}
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

compile_schema() {
  "$CAPNP" compile --src-prefix="$ROOT/tests" -I"$ROOT/tests" -I"$ROOT/compiler" \
    -o"$CAPNPC:$TMP" "$@"
}

compile_schema "$ROOT/tests/a.capnp"
compile_schema "$ROOT/tests/e.capnp"
compile_schema "$ROOT/tests/b.capnp"
compile_schema "$ROOT/tests/brand-reuse.capnp"
compile_schema "$ROOT/tests/a.capnp" "$ROOT/tests/brand-multifile.capnp"

for h in e b brand-reuse; do
  if ! grep -q '^#ifndef CAPNP_C_BRAND_Box_Text$' "$TMP/$h.capnp.h"; then
    echo "$h.capnp.h does not guard Box_Text" >&2
    exit 1
  fi
done
if grep -q 'Local' "$TMP/a.capnp.h"; then
  echo "a.capnp.h leaked a downstream brand argument" >&2
  exit 1
fi
if ! grep -q 'struct Box_Local {' "$TMP/brand-multifile.capnp.h"; then
  echo "brand-multifile.capnp.h is missing its local brand" >&2
  exit 1
fi

cat >"$TMP/consumer.c" <<'EOF'
#include "a.capnp.h"
#include "b.capnp.h"
#include "e.capnp.h"
#include "brand-reuse.capnp.h"
#include <string.h>
int main(void) {
	struct capn c;
	struct capn_segment *s;
	struct U u;
	struct F f;
	struct Nest nest;
	struct Box_Text bt;
	struct Box_Box_Data bb;
	struct Box_Data bd;
	(void)c1;
	capn_init_malloc(&c);
	s = capn_root(&c).seg;
	memset(&bt, 0, sizeof bt);
	bt.val.str = "hi";
	bt.val.len = 2;
	memset(&u, 0, sizeof u);
	u.t = new_Box_Text(s);
	write_Box_Text(&bt, u.t);
	memset(&f, 0, sizeof f);
	f.t = u.t;
	memset(&bt, 0, sizeof bt);
	read_Box_Text(&bt, f.t);
	if (bt.val.len != 2 || memcmp(bt.val.str, "hi", 2) != 0)
		return 1;
	memset(&nest, 0, sizeof nest);
	read_Box_Box_Data(&bb, nest.inner);
	read_Box_Data(&bd, bb.val);
	capn_free(&c);
	return 0;
}
EOF

compilers=$CC
if [ -z "${EXE_WRAPPER:-}" ] && command -v clang >/dev/null 2>&1; then
  compilers="$CC clang"
fi
for cc in $compilers; do
  for f in a.capnp e.capnp b.capnp brand-reuse.capnp brand-multifile.capnp consumer; do
    "$cc" -std=c99 -pedantic -Wall -Werror -I"$TMP" -I"$ROOT/lib" \
      -c -o "$TMP/check-$f.o" "$TMP/$f.c"
  done
done
"$CXX" -x c++ -std=c++14 -pedantic-errors -Wall -Werror -I"$TMP" -I"$ROOT/lib" \
  -c -o "$TMP/check-consumer-cpp.o" "$TMP/consumer.c"

# `SAN_FLAGS` is the sanitizer list the library was built with. A
# clang build links the runtime into each program, so the library
# only names the symbols, and `ldd` shows no runtime.
SAN=${SAN_FLAGS:-}
if [ -z "$SAN" ] && { ldd "$LIB" 2>/dev/null | grep -q libasan ||
  nm -D --undefined-only "$LIB" 2>/dev/null | grep -q ' __[a-z]*san_'; }; then
  SAN="-fsanitize=address,undefined"
fi
"$CC" -std=c99 -pedantic $SAN -I"$TMP" -I"$ROOT/lib" \
  -L"$(dirname "$LIB")" -Wl,-rpath,"$(dirname "$LIB")" \
  -o "$TMP/consumer" \
  "$TMP/consumer.c" "$TMP/a.capnp.c" "$TMP/e.capnp.c" "$TMP/b.capnp.c" \
  "$TMP/brand-reuse.capnp.c" -lcapnp_c
run_bin "$TMP/consumer"
